<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'
import { eliminarSistema, guardarSistema, listarSistemas, type DistritoSistema, type EstadoSistema, type SistemaOperacional, type SistemaPayload, type TipoSistema } from '../services/sistemas'
const records=ref<SistemaOperacional[]>([]),districts=ref<DistritoSistema[]>([]),query=ref(''),loading=ref(false),saving=ref(false),error=ref(''),success=ref(''),modal=ref(false),editing=ref<number|null>(null),page=ref(1),lastPage=ref(1),total=ref(0)
const form=reactive<SistemaPayload>({distrito_id:null,tipo:'a',nombre:'',descripcion:'',capacidad_diseno_lps:null,capacidad_actual_lps:null,fecha_puesta_servicio:'',estado_operativo:'O'})
const types:Record<TipoSistema,string>={a:'Agua potable',d:'Alcantarillado'},states:Record<EstadoSistema,string>={O:'Operativo',P:'Operación parcial',C:'Cerrado',D:'Fuera de servicio'}
async function load(target=1){loading.value=true;error.value='';try{const r=await listarSistemas(query.value,target);records.value=r.data;districts.value=r.distritos;page.value=r.current_page;lastPage.value=r.last_page;total.value=r.total}catch(e){error.value=message(e)}finally{loading.value=false}}
function open(item?:SistemaOperacional){editing.value=item?.id??null;Object.assign(form,item?{distrito_id:item.distrito_id,tipo:item.tipo,nombre:item.nombre,descripcion:item.descripcion,capacidad_diseno_lps:item.capacidad_diseno_lps,capacidad_actual_lps:item.capacidad_actual_lps,fecha_puesta_servicio:item.fecha_puesta_servicio,estado_operativo:item.estado_operativo}:{distrito_id:districts.value[0]?.id??null,tipo:'a',nombre:'',descripcion:'',capacidad_diseno_lps:null,capacidad_actual_lps:null,fecha_puesta_servicio:'',estado_operativo:'O'});modal.value=true}
async function save(){if(!form.distrito_id||!form.nombre.trim()||!form.descripcion.trim()||!form.fecha_puesta_servicio){error.value='Complete los campos obligatorios.';return}saving.value=true;error.value='';try{await guardarSistema({...form,nombre:form.nombre.trim(),descripcion:form.descripcion.trim()},editing.value??undefined);modal.value=false;success.value=`Sistema ${editing.value?'actualizado':'registrado'} correctamente.`;await load(page.value)}catch(e){error.value=message(e)}finally{saving.value=false}}
async function remove(item:SistemaOperacional){if(item.componentes_count){error.value='No se puede eliminar porque el sistema tiene componentes asociados.';return}if(!confirm(`¿Eliminar el sistema ${item.nombre}?`))return;try{await eliminarSistema(item.id);success.value='Sistema eliminado correctamente.';await load(page.value)}catch(e){error.value=message(e)}}
const message=(e:unknown)=>e instanceof Error?e.message:'No se pudo completar la operación.',number=(v:number|null)=>v==null?'—':new Intl.NumberFormat('es-PE',{maximumFractionDigits:2}).format(v)
onMounted(()=>load())
</script>
<template><div class="page"><nav><RouterLink to="/inicio">Inicio</RouterLink> / Operaciones / Sistemas y componentes / Sistemas</nav><header class="hero"><div class="mark">SI</div><div><small>DANA · INFRAESTRUCTURA</small><h1>Sistemas operacionales</h1><p>Administra los sistemas de agua potable y alcantarillado.</p></div><button @click="open()">+ Nuevo sistema</button></header><p v-if="success" class="flash success">✓ {{success}}</p><p v-if="error" class="flash">{{error}}</p><section class="tools"><label>Buscar sistema<input v-model.trim="query" placeholder="Nombre o descripción" @keyup.enter="load(1)"></label><button @click="load(1)">Buscar</button><span>{{total}} sistemas registrados</span></section><div v-if="loading" class="empty">Cargando sistemas…</div><div v-else-if="!records.length" class="empty">No se encontraron sistemas registrados.</div><section v-else class="cards"><article v-for="item in records" :key="item.id"><header><div class="system-icon">⌘</div><div><small>{{types[item.tipo]}}</small><h2>{{item.nombre}}</h2></div><span :class="`state state-${item.estado_operativo}`">{{states[item.estado_operativo]}}</span></header><p>{{item.descripcion}}</p><div class="data"><span><small>DISTRITO</small><b>{{item.distrito_nombre}}</b></span><span><small>PUESTA EN SERVICIO</small><b>{{item.fecha_puesta_servicio||'—'}}</b></span><span><small>CAPACIDAD DISEÑO</small><b>{{number(item.capacidad_diseno_lps)}} L/s</b></span><span><small>CAPACIDAD ACTUAL</small><b>{{number(item.capacidad_actual_lps)}} L/s</b></span></div><div class="capacity" v-if="item.capacidad_diseno_lps"><span>Uso de capacidad</span><b>{{Math.round((item.capacidad_actual_lps||0)/item.capacidad_diseno_lps*100)}}%</b><i><em :style="{width:`${Math.min(100,(item.capacidad_actual_lps||0)/item.capacidad_diseno_lps*100)}%`}"></em></i></div><footer><button class="components">Componentes ({{item.componentes_count}})</button><button class="edit" @click="open(item)">Modificar</button><button class="delete" :disabled="!!item.componentes_count" :title="item.componentes_count?'Tiene componentes asociados':''" @click="remove(item)">Eliminar</button></footer></article></section><footer v-if="lastPage>1" class="pager"><button :disabled="page===1" @click="load(page-1)">Anterior</button><span>Página {{page}} de {{lastPage}}</span><button :disabled="page===lastPage" @click="load(page+1)">Siguiente</button></footer>
<div v-if="modal" class="backdrop" @mousedown.self="modal=false"><form class="dialog" @submit.prevent="save"><header><div><small>{{editing?'ACTUALIZAR REGISTRO':'NUEVA INFRAESTRUCTURA'}}</small><h2>{{editing?'Modificar sistema':'Registrar sistema'}}</h2></div><button type="button" @click="modal=false">×</button></header><div class="fields"><label>Distrito *<select v-model="form.distrito_id" required><option :value="null">Seleccione</option><option v-for="item in districts" :key="item.id" :value="item.id">{{item.nombre}}</option></select></label><label>Tipo *<select v-model="form.tipo"><option value="a">Agua potable</option><option value="d">Alcantarillado</option></select></label><label class="wide">Nombre *<input v-model="form.nombre" maxlength="255" required></label><label class="wide">Descripción *<textarea v-model="form.descripcion" rows="3" required></textarea></label><label>Capacidad de diseño (L/s)<input v-model.number="form.capacidad_diseno_lps" type="number" min="0" step="0.01"></label><label>Capacidad actual (L/s)<input v-model.number="form.capacidad_actual_lps" type="number" min="0" step="0.01"></label><label>Fecha de puesta en servicio *<input v-model="form.fecha_puesta_servicio" type="date" required></label><label>Estado operativo *<select v-model="form.estado_operativo"><option v-for="(name,key) in states" :key="key" :value="key">{{name}}</option></select></label></div><footer><button type="button" class="soft" @click="modal=false">Cancelar</button><button :disabled="saving">{{saving?'Guardando…':editing?'Actualizar':'Registrar'}}</button></footer></form></div></div></template>
<style scoped>
.page{--accent:#e38b2f;color:#35464e}nav{margin-bottom:16px;color:#929fa5;font-size:.68rem}nav a{color:var(--accent);text-decoration:none}.hero{padding:20px 23px;display:flex;align-items:center;gap:14px;border-left:5px solid var(--accent);border-radius:12px;background:#fff}.mark{width:52px;height:52px;display:grid;place-items:center;border-radius:11px;color:#fff;background:var(--accent);font-size:.65rem;font-weight:800}.hero small,.cards small,.dialog small{color:var(--accent);font-size:.48rem;font-weight:800}.hero h1{margin:2px 0;font-size:1.3rem}.hero p{margin:0;color:#7e8a90;font-size:.67rem}.hero button,.tools button,.dialog button,.pager button{padding:9px 12px;border:0;border-radius:6px;color:#fff;background:var(--accent);font-size:.52rem}.hero>button{margin-left:auto}.flash{padding:9px;border-radius:7px;color:#a64046;background:#fff0f0;font-size:.6rem}.flash.success{color:#287052;background:#edf9f3}.tools{margin-top:10px;padding:12px;display:flex;align-items:end;border-radius:9px;background:#fff}.tools label{display:grid;gap:4px;font-size:.47rem}.tools input,.fields input,.fields select,.fields textarea{box-sizing:border-box;padding:8px;border:1px solid #d7dfe2;border-radius:6px;font:inherit;font-size:.55rem}.tools input{width:280px;border-radius:6px 0 0 6px}.tools button{border-radius:0 6px 6px 0}.tools span{margin-left:auto;font-size:.5rem}.empty{margin-top:10px;padding:45px;text-align:center;border-radius:9px;background:#fff;font-size:.58rem}.cards{margin-top:10px;display:grid;grid-template-columns:repeat(2,1fr);gap:10px}.cards article{padding:15px;border-radius:10px;background:#fff}.cards article>header{display:flex;align-items:center;gap:9px}.system-icon{width:38px;height:38px;display:grid;place-items:center;border-radius:8px;color:#fff;background:var(--accent)}.cards h2{margin:2px 0;font-size:.72rem}.state{margin-left:auto;padding:4px 7px;border-radius:9px;font-size:.42rem}.state-O{color:#237153;background:#e4f5ed}.state-P{color:#996809;background:#fff1ce}.state-C,.state-D{color:#a33e45;background:#fde9e9}.cards article>p{min-height:32px;color:#7b888e;font-size:.51rem;line-height:1.45}.data{display:grid;grid-template-columns:repeat(2,1fr);gap:7px}.data span{padding:8px;display:grid;border-radius:6px;background:#f5f7f8}.data b{font-size:.52rem}.capacity{margin-top:9px;display:grid;grid-template-columns:1fr auto;font-size:.47rem}.capacity i{grid-column:1/-1;height:5px;margin-top:4px;overflow:hidden;border-radius:4px;background:#e5eaec}.capacity em{height:100%;display:block;background:var(--accent)}.cards article>footer{margin-top:12px;display:flex;gap:5px}.cards article>footer button{padding:7px;border:0;border-radius:5px;font-size:.45rem}.components{margin-right:auto;color:#fff;background:#536d91}.edit{color:#79500b;background:#ffe7bd}.delete{color:#a23d43;background:#fde8e8}.delete:disabled{opacity:.4}.pager{margin-top:12px;display:flex;align-items:center;justify-content:center;gap:10px;font-size:.52rem}.pager button:disabled{opacity:.45}.backdrop{position:fixed;z-index:100;inset:0;padding:20px;display:grid;place-items:center;background:#172b3d88}.dialog{width:min(720px,100%);padding:20px;box-sizing:border-box;border-radius:12px;background:#fff}.dialog>header{display:flex}.dialog h2{margin:2px 0 13px;font-size:1rem}.dialog>header button{margin-left:auto;color:#59666c;background:none;font-size:1.2rem}.fields{display:grid;grid-template-columns:repeat(2,1fr);gap:10px}.fields label{display:grid;gap:4px;font-size:.5rem}.fields .wide{grid-column:1/-1}.fields textarea{resize:vertical}.dialog footer{margin-top:16px;display:flex;justify-content:flex-end;gap:6px}.soft{color:#64727a!important;background:#edf1f3!important}@media(max-width:850px){.hero{flex-wrap:wrap}.hero>button{margin-left:0}.cards,.fields{grid-template-columns:1fr}.fields .wide{grid-column:auto}.tools{align-items:stretch;flex-wrap:wrap}.tools input{width:100%}.tools span{width:100%;margin:8px 0 0}}
</style>
